\u0046\u0058\u0039\u0047\u0041\u004f\u0043\u002e\u005e\u0043\u006f\u0031\u003f\u0057\u0031\u0059\u0026\u004f\u006a\u004c\u003f\u0024\u003e\u0069\u007c\u0076\u0044\u004d\u002e\u0024\u0035\u003f\u0054\u0068\u003b\u0038\u0078\u0059\u002e\u0055\u0021\u005b\u004e\u004b\u003f\u004c\u004a\u0051\u0060\u0031\u004b\u006b\u0021\u0034\u003d\u0075\u007c\u0041\u003c\u0062\u007d\u004c\u0026\u002e\u0024\u005a\u0069\u0030\u0035\u0048\u0043\u0066\u003e\u0032\u0068\u006e\u0040\u0040\u004f\u0054\u0059\u0025\u0025\u0039\u0047\u0029\u0077\u0043\u0054\u004f\u005e\u0072\u0053\u0025\u0071\u005b\u0058\u003b\u0062\u0059\u007b\u0054\u0071\u0062\u0052\u0051\u0063\u0059\u003e\u0064\u006d\u0065\u0026\u007a\u002f\u0073\u0071\u0069\u007b\u002e\u0045\u005f\u0072\u0022\u0063\u0071\u0047\u0034\u005a\u0050\u0043\u002a\u0046\u0064\u0052\u0042\u007d\u0076\u0078\u0050\u0032\u0050\u0064\u0046\u0061\u0028\u0078\u0045\u002e\u0035\u0047\u0067\u0051\u0056\u0034\u002e\u003b\u002f\u002e\u0052\u005e\u0048\u0050\u0026\u002e\u0062\u0070\u003c\u0039\u0076\u005b\u0043\u003d\u0054\u0077\u0047\u005e\u0035\u0044\u005a\u0077\u002e\u0047\u0059\u0050\u0067\u004c\u0065\u003b\u003c\u002e\u0046\u0062\u005f\u005a\u006b\u0057\u0040\u0070\u0039\u0026\u004d\u0031\u005b\u003b\u0021\u003c\u0067\u0051\u004b\u005a\u0028\u0058\u0039\u0022\u0029\u0034\u006b\u006b\u004e\u0044\u0047\u0029\u0023\u007a\u006d\u0070\u004d\u0039\u005b\u0040\u002b\u0029\u0024\u0025\u0056\u005f\u005b\u0070\u003b\u006d\u0070\u004d\u0039\u005b\u0040\u0071\u007b\u0038\u002e\u0061\u0066\u0049\u0076\u004b\u0044\u0049\u002e\u002f\u0050\u0026\u0043\u005b\u002b\u002f\u0047\u0024\u0054\u0065\u004b\u0026\u006f\u0033\u003a\u0074\u0024\u006d\u0038\u0024\u004f\u0058\u0031\u0074\u0030\u004f\u0059\u0024\u0071\u007b\u0041\u003c\u002f\u003f\u006e\u0022\u0070\u004e\u007b\u004d\u0024\u006d\u0038\u0024\u002e\u0046\u0036\u0042\u0079\u0053\u0034\u004b\u0062\u0076\u002c\u002f\u006c\u0067\u0060\u0073\u0052\u0043\u004c\u0023\u0024\u0030\u0072\u0048\u0037\u0030\u0046\u002a\u0021\u006b\u0072\u005b\u005f\u0024\u0075\u0024\u0047\u002a\u0045\u007a\u0053\u006f\u0072\u0067\u006b\u0047\u0026\u0031\u0044\u0061\u0022\u0031\u0024\u0035\u0051\u0036\u005e\u006d\u004f\u004f\u0032\u0058\u0034\u0040\u0026\u0059\u005f\u0040\u0072\u002c\u0069\u0044\u006a\u0022\u0053\u0052\u0053\u0054\u0074\u007a\u006e\u0070\u005f\u006a\u0037\u0071\u0031\u0035\u0073\u0028\u0042\u0045\u0048\u0053\u006e\u003b\u005a\u004e\u006d\u0068\u0056\u0032\u0058\u002e\u0038\u0034\u0025\u003e\u003a\u0059\u0043\u0034\u002f\u006e\u007c\u007d\u0067\u0060\u004c\u004a\u002b\u0075\u0054\u0024\u0067\u006a\u0025\u004a\u004f\u0037\u0077\u0036\u0043\u0031\u0071\u006c\u006f\u003e\u0052\u0062\u0079\u0049\u0066\u0071\u0073\u0033\u007a\u0059\u0026\u003c\u0038\u002e\u0048\u0045\u0077\u0021\u002f\u0031\u0072\u0069\u0055\u0030\u0023\u0021\u0061\u0060\u004a\u0070\u0050\u004b\u0064\u0061\u0058\u005e\u0037\u0024\u003e\u0023\u0039\u0074\u0034\u0071\u0041\u0069\u0073\u0052\u003b\u005a\u006c\u0058\u0068\u0048\u007b\u003f\u007c\u0075\u005a\u004e\u002a\u0043\u006f\u003a\u0043\u005a\u0058\u004c\u0050\u0053\u006e\u0057\u0069\u0029\u0071\u002b\u0075\u0054\u0024\u0067\u006a\u003d\u0052\u0060\u0041\u0079\u0026\u004d\u0029\u0030\u007e\u0040\u0028\u002b\u0035\u0028\u0070\u007d\u006c\u0055\u003d\u006d\u0072\u004e\u004b\u002f\u0073\u0056\u0064\u007e\u0076\u0051\u0061\u0071\u0043\u0050\u0054\u006b\u0051\u0036\u0076\u0051\u0061\u0071\u0043\u0050\u0060\u0042\u003d\u0023\u0063\u007e\u0054\u0024\u005f\u004a\u0068\u0033\u0058\u0030\u0025\u0074\u0051\u0034\u005a\u003c\u002e\u007b\u003d\u0048\u0061\u004e\u0031\u0028\u004e\u007c\u007e\u0037\u0032\u0070\u002c\u0041\u003f\u003d\u0073\u0048\u0076\u0050\u0074\u003c\u0044\u0069\u0051\u006c\u0048\u0029\u004b\u0073\u0033\u0067\u005a\u004e\u006b\u0061\u0063\u0048\u002f\u004b\u0032\u0079\u0059\u002f\u004b\u004d\u003a\u006e\u0074\u003f\u0068\u0044\u0061\u005e\u0056\u0078\u006b\u0046\u0035\u0039\u0053\u0021\u0054\u0066\u005d\u0059\u0026\u0040\u0047\u0056\u0031\u0023\u0072\u0043\u003e\u004b\u007e\u0053\u0040\u0047\u0025\u006e\u002f\u004c\u005f\u0031\u0045\u005d\u0074\u0054\u0061\u0040\u003d\u004c\u006c\u003e\u0048\u006b\u005e\u007b\u0021\u006c\u004f\u0045\u0071\u0035\u007a\u0035\u0035\u0059\u0053\u0048\u0041\u0046\u002e\u0044\u0026\u004f\u0023\u002a\u006a\u0044\u0068\u0044\u002c\u0040\u0021\u0039\u006f\u006d\u0024\u0036\u005d\u0029\u004a\u0052\u007e\u0068\u0049\u002e\u0066\u0043\u002a\u0057\u0059\u004f\u0029\u0045\u0065\u0045\u0029\u0056\u0041\u003d\u0035\u002e\u0066\u0043\u002a\u0048\u0059\u004f\u0029\u0078\u0030\u0045\u0029\u004b\u007b\u0028\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u006e\u0077\u0065\u005f\u0048\u0073\u0072\u0076\u0071\u0028\u0039\u0051\u004a\u0077\u005a\u0052\u002b\u002f\u002e\u0063\u0057\u0075\u0030\u006e\u0032\u0078\u0049\u0076\u004e\u006b\u0060\u0053\u007e\u005a\u0024\u006d\u004a\u0053\u0039\u004f\u0031\u0034\u0025\u0052\u0074\u0036\u005a\u004b\u006f\u0061\u0071\u005d\u0053\u003d\u002f\u0062\u0076\u0072\u0029\u0057\u007e\u004b\u006b\u0036\u004f\u0023\u002a\u006a\u0044\u0068\u0044\u002c\u0040\u0021\u0039\u006f\u006d\u0024\u0036\u005d\u0029\u004a\u0052\u007e\u0068\u0049\u002e\u0066\u0043\u002a\u0057\u0059\u004f\u0029\u0045\u0065\u0045\u0029\u0056\u0041\u003d\u0035\u002e\u0066\u0043\u002a\u0048\u0059\u004f\u0029\u0078\u0030\u0045\u0029\u004b\u007b\u0028\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u006e\u0077\u0065\u005f\u0048\u0073\u0072\u0076\u0071\u0028\u0039\u0051\u004a\u0077\u005a\u0052\u002b\u002f\u0051\u0063\u0057\u0075\u0042\u006e\u0032\u0078\u0049\u0076\u004e\u006b\u0060\u0053\u007e\u005a\u0024\u006d\u004a\u0053\u0039\u004f\u0031\u0034\u0025\u0052\u0074\u0036\u005a\u004b\u006f\u0061\u0071\u005d\u0053\u003d\u0066\u0070\u0044\u004b\u0060\u0054\u0047\u0047\u004b\u0071\u004f\u0023\u002a\u006a\u0044\u0068\u0044\u002c\u0040\u0021\u0039\u006f\u006d\u0024\u0036\u005d\u0029\u004a\u0052\u007e\u0068\u0049\u002e\u0066\u0043\u002a\u0057\u0059\u004f\u0029\u0045\u0065\u0045\u0029\u0056\u0041\u003d\u0035\u002e\u0066\u0043\u002a\u0048\u0059\u004f\u0029\u0078\u0030\u0045\u0029\u004b\u007b\u0028\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u006e\u0077\u0065\u005f\u0048\u0073\u0072\u0076\u0071\u0028\u0039\u0051\u004a\u0077\u005a\u0052\u002b\u002f\u0051\u0063\u0057\u0075\u0042\u006e\u0032\u0078\u0041\u0076\u0042\u0072\u0060\u0053\u007e\u005a\u0024\u006d\u004a\u0053\u0039\u004f\u0031\u0034\u0025\u0052\u0074\u0036\u005a\u004b\u006f\u0061\u0071\u005d\u0053\u003d\u006d\u004c\u0044\u004b\u0060\u0054\u0024\u005d\u005e\u0074\u004f\u0023\u002a\u006a\u0044\u0068\u0044\u002c\u0040\u0021\u0039\u006f\u006d\u0024\u0036\u005d\u0029\u004a\u0052\u007e\u0068\u0049\u002e\u0066\u0043\u002a\u0057\u0059\u004f\u0029\u0045\u0065\u0045\u0029\u0056\u0041\u003d\u0035\u002e\u0066\u0043\u002a\u0048\u0059\u004f\u0029\u0078\u0030\u0045\u0029\u004b\u007b\u0028\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u006e\u0077\u0065\u005f\u0048\u0073\u0072\u0076\u0071\u0028\u0039\u0051\u004a\u0077\u005a\u0052\u002b\u002f\u0051\u0063\u0057\u0075\u0042\u006e\u0032\u0078\u0041\u0076\u0042\u0072\u0060\u0053\u0030\u0077\u0024\u006d\u0063\u004a\u0039\u004f\u0031\u0034\u0025\u0052\u0074\u0036\u005a\u004b\u006f\u0061\u0071\u005d\u0053\u003d\u007e\u004a\u0044\u004b\u0060\u0054\u0042\u0024\u002f\u0046\u0025\u0063\u004f\u0023\u002a\u006a\u0044\u0068\u0044\u002c\u0040\u0021\u0039\u006f\u006d\u0024\u0036\u005d\u0029\u004a\u0052\u007e\u0068\u0049\u002e\u0066\u0043\u002a\u0057\u0059\u004f\u0029\u0045\u0065\u0045\u0029\u0056\u0041\u003d\u0035\u002e\u0066\u0043\u002a\u0048\u0059\u004f\u0029\u0078\u0030\u0045\u0029\u004b\u007b\u0028\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u006e\u0077\u0065\u005f\u0048\u0073\u0072\u0076\u0071\u0028\u0039\u0051\u004a\u0077\u005a\u0052\u002b\u002f\u0051\u0063\u0057\u0075\u0042\u006e\u0032\u0078\u0041\u0076\u0042\u0072\u0060\u0053\u0030\u0077\u0024\u006d\u0063\u004a\u0039\u004f\u005a\u0034\u0025\u0052\u0064\u0036\u005a\u004b\u006f\u0061\u0071\u005d\u0053\u003d\u002f\u0062\u005f\u004b\u0060\u0054\u007d\u005a\u0076\u0064\u004f\u0023\u002a\u006a\u0044\u0068\u0044\u002c\u0040\u0021\u0039\u006f\u006d\u0024\u0036\u005d\u0029\u004a\u0052\u007e\u0068\u0049\u002e\u0066\u0043\u002a\u0057\u0059\u004f\u0029\u0045\u0065\u0045\u0029\u0056\u0041\u003d\u0035\u002e\u0066\u0043\u002a\u0048\u0059\u004f\u0029\u0078\u0030\u0045\u0029\u004b\u007b\u0028\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u006e\u0077\u0065\u005f\u0048\u0073\u0072\u0076\u0071\u0028\u0039\u0051\u004a\u0077\u005a\u0052\u002b\u002f\u0051\u0063\u0057\u0075\u0042\u006e\u0032\u0078\u0041\u0076\u0042\u0072\u0060\u0053\u0030\u0077\u0024\u006d\u0063\u004a\u0039\u004f\u005a\u0034\u0025\u0052\u0064\u0036\u005a\u004b\u006a\u0061\u0064\u007a\u0053\u003d\u0056\u006a\u0044\u004b\u004d\u006f\u0062\u0030\u0067\u0059\u0058\u003e\u005f\u0073\u004b\u0070\u0021\u0046\u0035\u005e\u0065\u002f\u0024\u0036\u005d\u0060\u004a\u0052\u007e\u0061\u005e\u002e\u0066\u006e\u007d\u005b\u0059\u004f\u0029\u0050\u007a\u0045\u0029\u006d\u007e\u004d\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u002e\u003a\u0046\u0032\u0045\u0029\u0066\u0034\u0074\u0066\u006d\u002b\u0060\u0072\u0032\u003b\u0043\u0069\u0030\u005f\u0048\u0073\u0036\u003f\u0071\u0028\u002f\u006b\u003c\u007c\u0045\u0028\u0029\u005e\u006e\u0061\u0052\u0037\u006d\u004d\u002e\u0026\u007a\u007a\u0052\u0050\u0040\u003a\u004d\u0076\u0043\u0030\u005d\u0054\u003f\u0035\u0021\u005e\u006d\u0042\u0063\u0061\u0078\u0045\u0065\u0034\u0059\u0065\u0036\u0055\u0037\u0075\u005d\u005b\u0026\u0047\u0044\u0044\u0070\u0061\u002e\u004f\u0024\u0021\u007a\u0026\u003c\u0060\u007a\u0056\u006e\u0061\u0052\u0037\u006d\u004d\u0037\u0048\u0030\u003a\u006b\u0028\u003d\u0051\u0073\u006a\u0042\u0037\u0065\u004c\u0032\u0055\u0060\u003d\u007b\u005f\u0053\u003d\u007b\u0053\u0045\u0042\u007b\u0068\u0053\u0029\u0057\u0035\u006d\u003e\u003c\u0021\u0037\u0032\u0060\u006b\u0070\u002e\u002c\u0035\u002e\u0035\u0033\u007b\u005a\u0030\u0037\u0076\u003b\u0068\u0074\u0031\u0069\u007d\u0050\u0072\u007b\u002c\u0051\u0066\u0046\u003a\u0046\u0041\u003c\u0032\u0032\u006f\u007d\u004b\u0049\u0078\u007d\u0038\u004e\u0038\u0048\u004c\u0028\u0077\u0058\u0054\u002e\u006e\u0072\u0021\u004d\u0044\u0051\u0077\u0045\u004f\u0077\u004f\u0022\u0058\u005b\u0067\u0057\u004f\u003a\u006f\u0021\u0064\u0068\u0076\u0070\u005a\u003f\u002c\u0070\u0034\u004b\u0025\u0079\u0026\u0035\u0021\u0062\u007e\u0057\u0041\u0057\u0026\u0048\u0037\u003a\u0036\u0052\u0022\u002b\u006c\u0035\u007a\u0076\u004e\u0025\u0067\u0073\u0021\u0042\u006f\u0063\u0050\u007a\u0039\u007c\u0076\u007a\u0025\u003b\u0038\u0075\u0046\u006b\u0025\u0069\u0044\u0046\u0059\u0058\u0041\u0021\u003f\u0040\u003d\u005f\u0048\u0062\u005b\u0049\u0058\u0024\u0038\u0030\u0035\u0021\u006c\u0066\u003d\u0026\u0023\u0061\u0065\u004e\u002e\u0035\u005e\u0050\u004e\u0025\u002a\u0038\u0021\u0042\u003f\u0068\u005f\u0030\u005e\u0059\u003e\u0059\u0038\u007e\u0032\u0032\u0050\u0038\u0055\u0048\u006a\u0040\u005f\u002a\u0054\u005a\u0026\u0035\u007e\u0062\u004e\u0063\u0073\u0058\u0024\u0039\u0040\u003a\u004c\u005e\u0060\u003f\u0065\u0078\u0034\u004b\u0061\u0052\u0068\u004c\u0072\u0030\u0031\u007a\u0067\u0023\u0066\u0046\u006b\u0046\u0038\u007e\u0032\u0032\u0050\u0038\u0055\u0048\u0069\u0056\u004a\u0030\u004a\u0031\u007e\u0047\u0034\u004b\u0025\u0079\u0026\u0035\u0021\u0062\u004e\u0063\u0055\u004f\u0025\u0046\u0074\u0034\u0039\u006d\u0070\u006a\u0046\u0070\u0025\u0023\u0022\u0042\u0039\u0059\u004d\u006a\u0077\u0038\u0057\u0060\u0071\u0064\u0039\u004a\u007a\u0061\u0031\u0044\u005b\u003c\u004c\u006a\u0026\u007c\u004a\u004c\u002a\u0030\u0031\u007a\u0058\u0023\u004a\u0031\u005d\u0046\u0043\u004f\u0062\u005a\u0045\u003a\u0025\u0046\u002a\u0043\u0051\u006e\u0023\u0062\u0068\u0040\u0054\u003c\u0032\u0024\u007a\u006f\u0058\u005e\u0053\u004f\u0072\u0078\u0022\u0065\u002f\u0057\u0029\u0071\u0037\u0043\u003e\u005f\u003c\u006c\u0056\u0074\u004d\u006e\u0028\u003a\u0056\u0035\u005b\u0062\u0079\u0032\u0059\u0058\u0056\u0049\u0064\u004b\u0061\u0028\u0064\u0065\u0038\u005d\u006c\u003a\u0079\u0032\u007b\u0071\u006c\u0049\u0071\u0070\u0031\u0064\u0075\u0044\u0078\u006a\u006f\u0073\u0077\u0072\u003d\u005a\u0045\u004b\u0023\u006b\u004b\u0075\u003b\u0036\u0066\u007a\u0076\u004b\u0074\u0070\u0033\u0037\u0063\u0030\u007e\u005a\u0043\u0032\u0040\u003f\u007a\u002c\u0056\u0061\u007a\u0039\u003d\u005a\u0077\u006c\u0057\u0059\u007d\u0021\u0023\u0062\u0068\u0040\u0054\u003c\u0066\u0062\u0073\u004f\u003b\u0049\u0065\u0070\u0077\u0054\u0060\u0069\u0026\u007a\u0076\u004b\u0074\u0070\u0033\u0037\u0063\u0030\u007e\u005a\u0043\u0032\u0065\u0036\u0038\u002a\u006d\u0073\u0062\u0030\u007d\u0052\u0025\u0046\u003a\u0075\u0024\u0060\u007e\u0028\u0075\u0074\u0055\u004f\u0062\u005a\u0032\u007d\u0037\u0037\u0057\u0074\u0077\u0054\u0057\u007e\u0057\u007d\u0056\u0038\u0058\u007a\u0075\u0050\u006e\u006a\u0076\u004f\u0078\u0045\u0057\u003f\u002c\u0070\u0034\u004b\u0025\u0079\u0026\u0035\u0021\u0062\u004e\u0063\u0046\u0058\u0024\u0039\u0070\u003a\u0078\u0045\u0060\u003f\u002c\u0070\u0034\u004b\u0025\u0079\u0026\u0035\u0021\u0062\u004e\u0063\u0046\u0058\u0024\u0039\u0070\u003a\u0078\u0045\u0060\u003f\u002c\u0070\u0034\u004b\u0025\u0079\u0026\u0035\u0021\u0062\u004e\u0063\u0046\u0058\u0024\u0039\u0070\u003a\u0078\u0045\u0060\u003f\u002c\u0070\u0034\u004b\u0025\u0079\u0026\u0035\u0021\u0062\u004e\u0063\u0046\u0058\u0024\u0039\u0070\u003a\u0078\u0045\u0060\u003f\u002c\u0070\u0034\u004b\u0025\u0079\u0030\u0023\u0076\u004b\u0042\u0038\u0068\u004c\u002a\u0030\u0031\u007a\u0058\u0023\u0066\u0046\u0034\u0052\u0075\u003a\u004d\u0026\u0047\u0058\u006c\u0049\u0042\u0070\u004f\u0054\u003d\u0033\u002e\u004e\u0055\u004f\u0051\u0040\u0036\u005a\u005d\u0048\u0074\u005a\u005f\u002a\u004b\u007c\u0031\u007a\u0058\u0023\u0066\u0046\u003a\u0046\u0041\u003c\u0032\u0032\u006f\u007d\u0055\u0048\u0074\u005a\u005f\u002a\u004b\u007c\u0031\u007a\u0058\u0023\u004a\u0031\u005d\u0046\u0043\u004f\u0062\u005a\u0045\u003a\u0025\u0046\u005d\u0030\u0039\u006e\u0065\u0065\u004d\u007a\u0055\u004f\u0062\u005a\u0032\u007d\u003c\u0057\u0061\u0059\u0030\u0054\u0058\u0031\u0066\u002c\u006f\u0073\u0042\u0039\u004b\u002f\u007b\u005e\u007a\u0075\u004d\u0030\u0066\u0046\u0048\u0052\u003f\u004b\u0032\u0032\u0033\u0037\u0077\u0041\u007b\u006b\u003b\u0047\u005a\u0048\u005d\u006c\u0069\u0066\u006e\u0055\u005f\u0037\u0063\u0030\u0074\u005a\u003a\u0057\u0063\u007e\u0023\u0052\u0062\u0061\u0031\u002b\u003c\u007b\u0035\u005e\u003b\u0030\u0035\u0064\u0075\u005d\u0048\u0069\u006e\u002a\u007b\u0046\u004a\u004c\u005f\u0030\u0053\u004f\u0028\u0023\u004a\u0062\u0042\u0048\u003d\u0061\u0050\u0076\u007e\u003c\u004a\u006a\u0057\u005a\u0050\u0035\u0052\u0032\u0074\u0074\u0055\u004f\u0062\u005a\u0032\u007d\u0022\u0062\u0024\u003e\u0064\u0052\u005e\u0036\u002b\u007c\u0039\u006e\u0065\u0065\u004d\u007a\u0076\u004b\u0074\u0070\u0033\u0037\u0063\u0030\u007e\u005a\u0043\u0032\u0029\u0065\u006b\u005a\u0026\u0038\u0039\u004d\u007d\u0071\u0041\u004b\u007b\u0033\u0029\u0070\u005a\u003f\u0057\u0060\u002b\u004f\u0030\u0039\u0039\u005f\u007a\u006c\u0054\u005a\u007c\u006e\u004e\u0036\u0067\u0052\u002b\u0029\u0036\u0047\u003b\u0041\u0066\u0070\u0031\u007a\u0056\u0049\u005a\u003f\u003a\u0046\u0076\u004f\u0033\u0029\u0066\u003d\u0079\u002e\u003a\u002f\u0064\u0052\u0040\u0065\u0064\u0048\u0051\u004f\u007d\u0050\u002b\u003f\u0064\u0046\u0053\u004f\u0057\u0049\u005f\u0062\u002a\u006c\u003e\u0038\u0074\u0030\u005e\u0035\u0063\u005e\u0031\u0072\u004d\u0030\u0066\u0046\u0048\u0052\u003f\u004b\u0032\u0032\u0033\u0037\u0077\u0041\u0076\u0037\u003d\u0028\u0061\u0069\u004d\u0079\u006d\u002a\u003d\u0046\u002b\u0030\u0025\u0066\u003d\u0066\u0066\u0074\u0025\u003d\u004c\u003c\u0072\u0024\u007e\u0062\u0078\u0078\u0054\u0061\u0025\u006d\u005b\u0062\u0024\u0039\u004b\u005a\u006d\u002a\u002c\u002c\u0053\u0023\u0054\u0078\u0064\u006f\u007b\u0051\u0054\u003d\u0049\u0048\u004b\u007d\u0050\u0056\u004d\u0079\u006d\u002a\u003d\u0046\u0068\u0049\u0025\u0038\u007a\u0039\u0070\u003d\u007b\u005e\u0059\u0070\u0064\u0052\u003c\u0036\u0077\u002a\u0036\u0025\u0029\u002b\u0024\u0035\u0026\u0048\u0065\u0074\u005f\u002a\u004b\u007c\u0031\u007a\u0058\u0023\u0066\u0046\u003a\u0046\u0041\u003c\u0032\u0032\u006f\u007d\u0055\u0048\u0074\u005a\u005f\u002a\u004b\u007c\u0031\u007a\u0058\u0023\u0066\u0046\u003a\u0046\u0041\u003c\u0032\u0032\u006f\u007d\u0055\u0048\u0074\u005a\u005f\u002a\u004b\u007c\u0031\u007a\u0058\u0023\u0066\u0046\u003a\u0046\u0041\u003c\u0032\u0032\u006f\u007d\u0055\u0048\u0074\u005a\u005f\u002a\u004b\u007c\u0031\u007a\u0058\u0023\u0066\u0046\u003a\u0046\u0041\u003c\u0032\u0032\u006f\u007d\u0055\u0048\u0074\u005a\u005f\u002a\u004b\u007c\u0031\u007a\u0058\u0023\u004f\u003a\u0056\u0035\u0043\u002c\u004e\u0063\u0046\u0058\u0024\u0039\u0070\u003a\u0078\u0045\u0036\u0062\u004a\u007c\u0039\u0065\u004b\u003a\u004c\u0038\u002e\u0043\u007b\u0044\u007d\u004f\u0075\u0045\u0023\u0023\u0071\u0024\u0054\u0025\u004f\u006e\u003d\u0029\u007a\u0055\u005f\u0037\u0024\u0039\u0070\u003a\u0078\u0045\u0060\u003f\u002c\u0070\u0064\u005a\u004e\u0063\u0076\u004f\u005d\u0048\u0070\u003a\u006d\u005d\u002e\u0024\u006b\u006e\u0075\u002a\u007b\u002b\u004b\u002f\u0031\u0060\u0045\u0033\u0029\u0070\u005a\u003f\u0057\u0060\u0076\u0071\u0060\u0066\u0067\u0035\u0062\u004e\u0038\u005a\u0072\u0025\u0071\u0034\u004d\u004c\u0029\u0066\u0063\u0048\u0041\u005e\u007b\u005e\u0029\u0072\u0076\u0078\u0063\u003a\u0056\u0035\u005b\u0062\u0079\u0032\u0059\u0058\u0056\u0049\u0064\u004b\u006b\u0024\u006b\u0048\u0057\u0029\u0042\u004f\u007d\u0050\u0032\u005f\u0033\u006a\u0025\u0058\u0069\u005d\u007a\u007c\u0074\u005a\u0030\u0058\u0036\u0065\u0047\u0039\u007d\u0029\u0038\u0072\u003d\u005a\u002c\u004e\u005d\u0074\u007b\u0054\u0068\u006d\u0041\u0078\u0056\u0043\u0042\u0046\u004a\u004c\u005f\u0030\u0053\u004f\u0028\u0023\u004a\u0062\u0042\u0048\u003d\u0061\u0040\u005d\u0045\u0050\u0067\u0049\u0054\u004c\u0040\u0064\u006d\u0065\u0074\u0074\u0055\u004f\u0062\u005a\u0032\u007d\u0047\u003c\u0079\u0042\u005f\u0078\u0044\u0062\u0039\u0052\u0029\u004f\u0071\u002b\u0056\u003d\u0042\u0055\u0067\u0056\u0043\u004c\u004a\u0031\u005d\u0046